import XCTest
final class ProbeTests:XCTestCase {
func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var n=0;while !q.allElementsBoundByIndex.contains(where:{$0.isHittable}) && n<10{let e=q.firstMatch;let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name+app.debugDescription);return};b.tap()}
func type(_ f:XCUIElement,_ value:String){f.tap();XCTAssertTrue(XCUIApplication(bundleIdentifier:"com.example.fancy.dev").keyboards.firstMatch.waitForExistence(timeout:10));for c in value{f.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
func option(_ app:XCUIApplication,_ name:String){let q=app.otherElements.matching(NSPredicate(format:"label == %@",name));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);let e=q.firstMatch;var n=0;while !e.isHittable && n<8{let scroll=app.scrollViews.firstMatch;let up=e.frame.midY>=scroll.frame.minY+35;let from=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.72:0.35));let to=scroll.coordinate(withNormalizedOffset:CGVector(dx:0.5,dy:up ? 0.48:0.59));from.press(forDuration:0.1,thenDragTo:to);n+=1};XCTAssertTrue(e.isHittable,app.debugDescription);e.tap()}
func shot(_ app:XCUIApplication,_ name:String){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
func testNativeWithdrawnReadonlyThenBlock182(){continueAfterFailure=false;let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.terminate();app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:5){decline.tap()};tap(app,"Inbox, tab, 4 of 5");let card=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA Final Applicant")).firstMatch;XCTAssertTrue(card.waitForExistence(timeout:12),app.debugDescription);card.tap();XCTAssertTrue(app.staticTexts["Native H reply after our M3 mutual choice."].firstMatch.waitForExistence(timeout:12),app.debugDescription);XCTAssertTrue(app.staticTexts["Hello native H after our M3 mutual choice."].firstMatch.exists);XCTAssertFalse(app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch.exists,app.debugDescription);shot(app,"native182-withdrawn-direct-readonly");print("QA_NATIVE182_WITHDRAWN_READONLY\n"+app.debugDescription);tap(app,"Back");tap(app,"Meals, tab, 2 of 5");option(app,"Past");let label="A relaxed meal together, Fri 23 Oct · 00:00 BST, 2 of 2 confirmed";let q=app.buttons.matching(NSPredicate(format:"label == %@",label));XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);var found=false;for index in 0..<q.count{app.buttons.matching(NSPredicate(format:"label == %@",label)).element(boundBy:index).tap();if app.buttons["After the meal"].waitForExistence(timeout:3){found=true;break};tap(app,"Back")};XCTAssertTrue(found,app.debugDescription);let prof=app.buttons.matching(NSPredicate(format:"label CONTAINS %@","QA Final Applicant")).firstMatch;var n=0;while !prof.isHittable && n<6{app.scrollViews.firstMatch.swipeUp();n+=1};print("QA_NATIVE_MEAL_DETAIL\n"+app.debugDescription);XCTAssertTrue(prof.isHittable,app.debugDescription);prof.tap();let block=app.buttons["Block QA Final Applicant"];XCTAssertTrue(block.waitForExistence(timeout:12),app.debugDescription);block.tap();tap(app,"Confirm block");XCTAssertTrue(app.staticTexts["Member blocked. Private contact is disabled. Shared groups are unchanged."].firstMatch.waitForExistence(timeout:10),app.debugDescription);XCTAssertTrue(app.buttons["Unblock QA Final Applicant"].exists);shot(app,"native182-blocked");print("QA_NATIVE182_BLOCK_PASS\n"+app.debugDescription)}
}
